sources=[('TPS54202_RevC.pdf','https://www.ti.com/lit/ds/symlink/tps54202.pdf',[3]),('TLV755P_RevD.pdf','https://www.ti.com/lit/ds/symlink/tlv755p.pdf',[4,16]),('STM32F103_DS5319_Rev20.pdf','https://www.st.com/resource/en/datasheet/stm32f103c8.pdf',[])]
manifest=[]
for name,url,pages in sources:
 f=S/name
 if not f.exists():
  if name.startswith('STM32'):
   shutil.copy2(H/'source/DS5319_Rev20_STM32F103x8xB_ST_20261022.pdf',f)
  else:f.write_bytes(urllib.request.urlopen(url,timeout=30).read())
 pdf=pymupdf.open(f);outs=[]
 for page in pages:
  img=S/(f.stem+'_p'+str(page+1)+'.png');pdf[page].get_pixmap(matrix=pymupdf.Matrix(1.5,1.5)).save(img);outs.append(str(img))
 manifest.append({'file':str(f),'url':url,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'pages':len(pdf),'reviewPNGs':outs})
 pdf.close()
(S/'manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf8')
primary=[('VIN_RAW','J1','1','J1','2','Design input9-16V; first approved startup at9V, current limit to be confirmed'),('VIN_FUSED','F1',None,'J1','2','Fuse drop/continuity under known input and load'),('VIN_PROT','C1','1','C1','2','After fuse+reverse diode; no surge/TVS certification'),('VIN_PROT','U2','3','U2','1','Local buck input and startup/ripple'),('V5','C5','1','C5','2','Design nominal5.010815V; source calculation4.876105-5.145987V'),('V5','C8','1','C8','2','LDO input; compare to V5 under actual load'),('V3V3','C9','1','C9','2','Nominal3.3V; IC conditional static full-temperature1.5% window3.2505-3.3495V'),('V3V3','U1','1','U1','47','Verify actual supply terminal; do not probe fine pitch without suitable access'),('V3V3','U1','24','U1','23','Verify local MCU supply and ripple'),('V3V3','U1','36','U1','35','Verify local MCU supply and ripple'),('V3V3','U1','48','U1','47','Verify local MCU supply and ripple'),('V3V3','U5','3','U5','2','Verify CAN supply, loading and startup'),('USB_VBUS','J2','A4_B9','J2','A1_B12','Sense only, never supply V5/V3V3; host/cable conditions recorded')]
for v in ['2L','4L']:
 n=json.loads((H/f'inventory/checkpoints/padentry_{v}_b019_DRC_PENDING/normalized.json').read_text(encoding='utf8'))
 board=H/f'native_candidates/HI_{v}_padentry_normalized_b019_DRC_PENDING.brd';sha=hashlib.sha256(board.read_bytes()).hexdigest()
 comps={p['ref']:p for p in n['placements']}
 def pin(ref,num=None,net=None):
  ps=[p for p in comps[ref]['pins'] if p['number'] and (str(p['number'])==str(num) if num is not None else p['net']==net)]
  assert len(ps)==1,(ref,num,net,len(ps));return ps[0]
 measures=list(primary)
 for net in ['VDDA','NRST','BOOT0','BOOT1']:
  choices=[]
  for c in n['placements']:
   nets={p['net'] for p in c['pins'] if p['number']}
   if c['ref'].startswith(('C','R')) and net in nets and 'GND'in nets:choices.append(c)
  if choices:
   c=sorted(choices,key=lambda c:(not c['ref'].startswith('C'),int(c['ref'][1:])))[0]
   measures.append((net,c['ref'],None,c['ref'],None,'Nominal3.3V after R26; check noise and reference' if net=='VDDA' else 'Verify default pull state/ramp under actual assembly; logic thresholds per ST'))
 rows=[];points=[]
 for idx,(net,ref,num,gr,gn,expect) in enumerate(measures,1):
  p=pin(ref,num,net);g=pin(gr,gn,'GND');assert p['net']==net and g['net']=='GND'
  ident=f'JK59-{v}-{idx:02d}';xy=p['xy'];gx=g['xy']
  rows.append([ident,v,net,ref+'.'+str(p['number']),*xy,gr+'.'+str(g['number']),*gx,expect,'NOT_MEASURED','NOT_SET','NOT_RUN','NONE',sha])
  points.append({'id':ident,'label':str(idx),'net':net,'point':ref+'.'+str(p['number']),'xy':xy,'groundPoint':gr+'.'+str(g['number']),'groundXY':gx,'expectation':expect,'measurement':None,'result':'NOT_RUN'})
 p=J/f'bench/{v}_measurement_sheet_NOT_RUN.csv'
 with p.open('w',encoding='utf-8-sig',newline='') as f:w=csv.writer(f);w.writerow(D['headers']);w.writerows(rows)
 with p.open(encoding='utf-8-sig',newline='') as f:back=list(csv.reader(f));assert len(back)==len(rows)+1 and all(len(r)==len(D['headers']) for r in back)
 geo=[]
 for c in n['placements']:
  bb=c.get('bodyExtent')
  if bb:
   (x1,y1),(x2,y2)=bb;geo.append(f'<rect x="{x1}" y="{60-y2}" width="{x2-x1}" height="{y2-y1}" fill="#edf0f4" stroke="#b5becb" stroke-width=".08"/>')
 for k in points:
  x,y=k['xy'];geo.append(f'<circle cx="{x}" cy="{60-y}" r=".38" fill="#d73a49"/><text x="{x+.5}" y="{60-y-.4}" font-size="1.5" fill="#003b65">{k["label"]}</text>')
 svg='<svg xmlns="http://www.w3.org/2000/svg" width="260mm" height="220mm" viewBox="-3 -8 86 72"><rect x="-3" y="-8" width="86" height="72" fill="white"/><text x="0" y="-5" font-size="2.1">JK59 '+v+' - ACTUAL b019 PAD PROBE CANDIDATES - ALL NOT RUN</text><text x="0" y="-2" font-size="1.4">No test access, connectivity or fabrication acceptance. See CSV for GND reference and expected conditions.</text><polygon points="2,60 78,60 80,58 80,2 78,0 2,0 0,2 0,58" fill="none" stroke="#172b4d" stroke-width=".2"/>'+''.join(geo)+'</svg>'
 svgp=J/f'bench/{v}_actual_probe_candidates_NOT_RUN.svg';svgp.write_text(svg,encoding='utf8')
 imgdoc=pymupdf.open('svg',svg.encode());imgdoc[0].get_pixmap(matrix=pymupdf.Matrix(1.4,1.4)).save(str(svgp.with_suffix('.png')))
 report={'variant':v,'status':'TEST_PLAN_ONLY_ALL_MEASUREMENTS_NOT_RUN','boardSHA256':sha,'coordinateSystem':'Native board absolute mm; component pad XY; top view Y+ upward. SVG displays Y reversed for page only.','notCertifiedAsTestPoints':True,'powerInputDesignV':[9,16],'V3V3NormalLoadMaxA':.15,'externalGPIOAndHeadersCombinedMaxA':.01,'ambientDesignC':[0,40],'initialCurrentLimitA':None,'initialCurrentLimitReason':'Confirm from actual assembly, startup and safe power budget; not fuse rating or output rail load rating.','points':points}
 (J/f'bench/{v}_bench_plan.json').write_text(json.dumps(report,indent=2),encoding='utf8')
source_records=[]
for p in [R/'learning/examples/de_15_26_20261019/power_interface_spec.json',R/'learning/examples/de_15_26_20261019/integrated_circuit.json']:
 source_records.append({'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(J/'bench/source_inputs.json').write_text(json.dumps(source_records,indent=2),encoding='utf8')
note=R/'learning/notes/lessonJK_59_bench_20261022.md';note.write_text(D['title']+'\n\n'+D['intro']+'\n\n'+D['text']+'\n\n## 已生成的实操产物\n\n两板各17个实际焊盘候选测点、独立公共地参考与绝对毫米坐标；CSV写后重读行数/字段通过，测值均NOT_MEASURED、结果均NOT_RUN。文件见[测试目录](../examples/lessonJK_51_59_20261022/bench/)。原点与视图说明在JSON，测点图不是Cadence GUI截图，也不代表可接触/可量产的测试点设计。\n',encoding='utf8')
print(json.dumps({'note':str(note),'measurementsPerVariant':len(primary)+4,'sourcePDFs':len(manifest),'measured':0,'results':'ALL_NOT_RUN'},ensure_ascii=True))
